import { redis } from '../db/redis';
import { config, redisKeys } from '../config';
import { logger } from '../lib/logger';

/**
 * Atomic Redis admission.
 *
 * KEYS[1] available stock counter
 * KEYS[2] reservation hash (orderId -> record JSON)
 * KEYS[3] idempotency record for this request key
 *
 * ARGV[1] orderId (pre-generated by the API)
 * ARGV[2] SHA-256 payload hash
 * ARGV[3] ISO timestamp
 *
 * Idempotency is checked before the counter, so a replay never consumes a unit.
 * Redis is only an admission gate. PostgreSQL remains the durable ledger and
 * applies its own capacity guard inside the checkout transaction.
 */
const RESERVE_LUA = `
local stockKey = KEYS[1]
local reservationsKey = KEYS[2]
local idempotencyKey = KEYS[3]

local orderId = ARGV[1]
local payloadHash = ARGV[2]
local createdAt = ARGV[3]
local idempotencyKeyValue = ARGV[4]

local existing = redis.call('GET', idempotencyKey)
if existing then
  local record = cjson.decode(existing)
  if record.payloadHash ~= payloadHash then
    return {'ERR_IDEMPOTENCY_MISMATCH', record.orderId}
  end
  local stock = redis.call('GET', stockKey)
  return {'SUCCESS_IDEMPOTENT', record.orderId, stock or '0'}
end

local stock = tonumber(redis.call('GET', stockKey) or '-1')
if stock < 0 then
  -- The counter has not been initialized yet. Refuse admission rather than
  -- guessing; the API startup/recovery path seeds it from PostgreSQL.
  return {'ERR_NOT_INITIALIZED', '0'}
end
if stock <= 0 then
  return {'ERR_SOLD_OUT', '0'}
end

local remaining = redis.call('DECR', stockKey)
if remaining < 0 then
  redis.call('INCR', stockKey)
  return {'ERR_SOLD_OUT', '0'}
end

local record = cjson.encode({
  orderId = orderId,
  payloadHash = payloadHash,
  createdAt = createdAt,
  idempotencyKey = idempotencyKeyValue,
})

redis.call('SET', idempotencyKey, record)
redis.call('HSET', reservationsKey, orderId, record)

return {'SUCCESS_NEW', tostring(remaining), orderId}
`;

/**
 * Compensation only restores a unit when the reservation hash still owns the
 * order. Repeating compensation is therefore safe. The idempotency record is
 * removed only when it belongs to the same order.
 */
const COMPENSATE_LUA = `
local stockKey = KEYS[1]
local reservationsKey = KEYS[2]
local idempotencyKey = KEYS[3]

local orderId = ARGV[1]

local removed = redis.call('HDEL', reservationsKey, orderId)
local idempotency = redis.call('GET', idempotencyKey)
if idempotency then
  local ok, record = pcall(cjson.decode, idempotency)
  if ok and record.orderId == orderId then
    redis.call('DEL', idempotencyKey)
  end
end

if removed == 1 then
  local stock = redis.call('INCR', stockKey)
  return {'COMPENSATED', tostring(stock)}
end

local stock = redis.call('GET', stockKey)
return {'NOT_FOUND', stock or '0'}
`;

/**
 * Development reset: never exposed over HTTP. The caller verifies in PostgreSQL
 * that no orders are processing before invoking this script.
 */
const RESET_LUA = `
local stockKey = KEYS[1]
local reservationsKey = KEYS[2]
local statsPrefix = ARGV[1]
local idempotencyPrefix = ARGV[2]
local eventsKey = ARGV[3]
local targetStock = ARGV[4]

redis.call('SET', stockKey, targetStock)
redis.call('DEL', reservationsKey)
redis.call('DEL', eventsKey)

local function deleteByPattern(pattern)
  local cursor = '0'
  repeat
    local result = redis.call('SCAN', cursor, 'MATCH', pattern, 'COUNT', 500)
    cursor = result[1]
    if #result[2] > 0 then
      redis.call('DEL', unpack(result[2]))
    end
  until cursor == '0'
end

deleteByPattern(statsPrefix .. '*')
deleteByPattern(idempotencyPrefix .. '*')

return {'RESET_OK', targetStock}
`;

const SEED_STOCK_LUA = `
local stockKey = KEYS[1]
local target = tonumber(ARGV[1])
local exists = redis.call('EXISTS', stockKey)
if exists == 0 then
  redis.call('SET', stockKey, target)
  return {1, target}
end
local current = redis.call('GET', stockKey)
return {0, tonumber(current)}
`;

const RELEASE_LUA = `
local stockKey = KEYS[1]
local reservationsKey = KEYS[2]
local orderId = ARGV[1]
local removed = redis.call('HDEL', reservationsKey, orderId)
if removed == 1 then
  redis.call('INCR', stockKey)
end
return removed
`;

export type ReserveResult =
  | { status: 'SUCCESS_NEW'; orderId: string; remainingStock: number }
  | { status: 'SUCCESS_IDEMPOTENT'; orderId: string; currentStock: number }
  | { status: 'ERR_SOLD_OUT' }
  | { status: 'ERR_IDEMPOTENCY_MISMATCH'; existingOrderId: string }
  | { status: 'ERR_NOT_INITIALIZED' };

export function idempotencyRedisKey(idempotencyKey: string): string {
  return `${redisKeys.idempotencyPrefix}${idempotencyKey}`;
}

export async function reserveUnit(params: {
  orderId: string;
  idempotencyKey: string;
  payloadHash: string;
}): Promise<ReserveResult> {
  const result = (await redis.eval(
    RESERVE_LUA,
    3,
    redisKeys.stock,
    redisKeys.reservations,
    idempotencyRedisKey(params.idempotencyKey),
    params.orderId,
    params.payloadHash,
    new Date().toISOString(),
    params.idempotencyKey,
  )) as [string, string, string?];

  switch (result[0]) {
    case 'SUCCESS_NEW':
      return {
        status: 'SUCCESS_NEW',
        orderId: result[2] ?? params.orderId,
        remainingStock: Number(result[1]),
      };
    case 'SUCCESS_IDEMPOTENT':
      return {
        status: 'SUCCESS_IDEMPOTENT',
        orderId: result[1],
        currentStock: Number(result[2] ?? 0),
      };
    case 'ERR_SOLD_OUT':
      return { status: 'ERR_SOLD_OUT' };
    case 'ERR_IDEMPOTENCY_MISMATCH':
      return { status: 'ERR_IDEMPOTENCY_MISMATCH', existingOrderId: result[1] };
    case 'ERR_NOT_INITIALIZED':
      return { status: 'ERR_NOT_INITIALIZED' };
    default:
      throw new Error(`Unexpected Redis reserve result: ${JSON.stringify(result)}`);
  }
}

export async function compensateReservation(params: {
  orderId: string;
  idempotencyKey: string;
}): Promise<{ status: 'COMPENSATED' | 'NOT_FOUND'; stock: number }> {
  const result = (await redis.eval(
    COMPENSATE_LUA,
    3,
    redisKeys.stock,
    redisKeys.reservations,
    idempotencyRedisKey(params.idempotencyKey),
    params.orderId,
  )) as [string, string];

  return {
    status: result[0] as 'COMPENSATED' | 'NOT_FOUND',
    stock: Number(result[1]),
  };
}

export async function releaseReservationKey(orderId: string): Promise<boolean> {
  const released = (await redis.eval(
    RELEASE_LUA,
    2,
    redisKeys.stock,
    redisKeys.reservations,
    orderId,
  )) as number;
  return released === 1;
}

export async function seedStockIfMissing(available: number): Promise<{ seeded: boolean; stock: number }> {
  const result = (await redis.eval(
    SEED_STOCK_LUA,
    1,
    redisKeys.stock,
    String(Math.max(0, available)),
  )) as [number, number];

  return { seeded: result[0] === 1, stock: Number(result[1]) };
}

export async function getAdmissionStock(): Promise<number> {
  const value = await redis.get(redisKeys.stock);
  return value === null ? -1 : Number(value);
}

export async function getReservationRecords(): Promise<
  Array<{ orderId: string; payloadHash: string; createdAt: string; idempotencyKey: string }>
> {
  const raw = await redis.hgetall(redisKeys.reservations);
  return Object.entries(raw).map(([orderId, json]) => {
    try {
      const parsed = JSON.parse(json) as {
        payloadHash: string;
        createdAt: string;
        idempotencyKey?: string;
      };
      return {
        orderId,
        payloadHash: parsed.payloadHash,
        createdAt: parsed.createdAt,
        idempotencyKey: parsed.idempotencyKey ?? '',
      };
    } catch {
      logger.warn('Malformed Redis reservation record', { orderId });
      return {
        orderId,
        payloadHash: '',
        createdAt: new Date(0).toISOString(),
        idempotencyKey: '',
      };
    }
  });
}

export async function resetRedisInventory(targetStock: number): Promise<void> {
  await redis.eval(
    RESET_LUA,
    2,
    redisKeys.stock,
    redisKeys.reservations,
    redisKeys.statsPrefix,
    redisKeys.idempotencyPrefix,
    redisKeys.events,
    String(targetStock),
  );
}

export function orphanGraceCutoff(): number {
  return Date.now() - config.REDIS_ORPHAN_GRACE_SECONDS * 1000;
}
